{"command":"cat <<'PY' > /tmp/p25.py
import subprocess,os,shutil,pathlib,hashlib
X="/workspace/executable"
def run(a):
 p=subprocess.run([X]+a,cwd="/tmp/t",capture_output=True,text=True)
 print("$",a,"exit",p.returncode,"OUT=",repr(p.stdout),"ERR=",repr(p.stderr)); return p
def fresh():
 shutil.rmtree("/tmp/t",ignore_errors=True);os.makedirs("/tmp/t")
def info(p):
 st=os.stat("/tmp/t/"+p); data=pathlib.Path("/tmp/t/"+p).read_bytes(); print(p,st.st_size,st.st_blocks,hashlib.sha256(data).hexdigest()[:12])

# sparse patterns with drivers and reflink never (to force data copy) and auto (reflink could preserve)
for driver in ["parfile","parblock"]:
 for refl in ["auto","never"]:
  fresh();
  with open("/tmp/t/a","wb") as f:
   f.write(b"start"); f.seek(1024*1024); f.write(b"mid"); f.seek(5*1024*1024); f.write(b"end")
  run(["--driver",driver,"--reflink",refl,"--no-progress","a","b"]); info("a"); info("b")
# all zeros non-sparse source 10MB with reflink never: dest sparse?
for driver in ["parfile","parblock"]:
 fresh(); pathlib.Path("/tmp/t/a").write_bytes(b"\x00"*(5*1024*1024))
 run(["--driver",driver,"--reflink","never","--no-progress","a","b"]); info("a"); info("b")
# binary random 10 MB integrity block sizes
import random
data=random.Random(1).randbytes(10*1024*1024+123)
for bs in ["1","100","4KB","64KB","1MB","10MB","0"]:
 fresh(); pathlib.Path("/tmp/t/a").write_bytes(data)
 run(["--driver","parblock","--reflink","never","--block-size",bs,"--no-progress","a","b"]); info("b")
for bs in ["1","0","100"]:
 fresh(); pathlib.Path("/tmp/t/a").write_bytes(data[:100000])
 run(["--driver","parfile","--reflink","never","--block-size",bs,"--no-progress","a","b"]); info("b")
PY
python3 /tmp/p25.py 2>&1 | head -n 250
"}

