{"command":"cat <<'PY' > /tmp/p26.py
import subprocess,os,pathlib,hashlib,shutil
X="/workspace/executable"
def make(p,fn):
 try:os.remove(p)
 except:pass
 fn(p)
def sparse(p):
 with open(p,"wb") as f:
  f.write(b"start");f.seek(1024*1024);f.write(b"mid");f.seek(5*1024*1024);f.write(b"end")
def zeros(p): pathlib.Path(p).write_bytes(b"\0"*5*1024*1024)
def info(p):
 st=os.stat(p); print(p,st.st_size,st.st_blocks,hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()[:8])
for driver in ["parfile","parblock"]:
 for maker,name in [(sparse,"sparse"),(zeros,"zeros")]:
  shutil.rmtree("/tmp/t",ignore_errors=True);os.makedirs("/tmp/t")
  make("/dev/shm/xcp_src",maker)
  p=subprocess.run([X,"--driver",driver,"--no-progress","/dev/shm/xcp_src","b"],cwd="/tmp/t",capture_output=True,text=True)
  print(driver,name,p.returncode,p.stderr); info("/dev/shm/xcp_src"); info("/tmp/t/b")
  # tmp to shm
  make("/tmp/t/a",maker)
  try:os.remove("/dev/shm/xcp_dest")
  except:pass
  p=subprocess.run([X,"--driver",driver,"--no-progress","a","/dev/shm/xcp_dest"],cwd="/tmp/t",capture_output=True,text=True)
  print("to shm",driver,name,p.returncode,p.stderr); info("/tmp/t/a"); info("/dev/shm/xcp_dest")
PY
python3 /tmp/p26.py
# filesystems
stat -f -c '%T %n' /tmp /dev/shm /workspace /proc 2>/dev/null || df -T /tmp /dev/shm /workspace
mount | head -n 30
"}

