import subprocess,os,shutil,pathlib
X="/workspace/executable"
def run(a):
 p=subprocess.run([X]+a,cwd="/tmp/t",capture_output=True,text=True)
 print("$",a,"exit",p.returncode,"OUT=",repr(p.stdout),"ERR=",repr(p.stderr))
 if os.path.exists("/tmp/t/b"):
  st=os.stat("/tmp/t/b"); print(" b size",st.st_size,"data",repr(pathlib.Path("/tmp/t/b").read_bytes()[:100]))
def fresh():
 shutil.rmtree("/tmp/t",ignore_errors=True);os.makedirs("/tmp/t")
for src in ["/sys/kernel/uevent_seqnum","/proc/version","/proc/uptime","/sys/devices/system/cpu/online","/proc/self/status"]:
 fresh(); 
 try: print(src,os.stat(src).st_size,repr(pathlib.Path(src).read_bytes()[:50]))
 except Exception as e: print(src,e)
 run(["--no-progress",src,"b"])
 fresh(); run(["--driver","parblock","--no-progress",src,"b"])
# /dev/zero size0 special char device mknod fails
fresh(); run(["--no-progress","/dev/zero","b"])
# /dev/stdin symlink to pipe? source existence/symlink copy
fresh(); run(["--no-progress","/dev/stdin","b"])
# changing size file? maybe use FUSE none.
# sparse destination in parblock reflink never same overlay but sizes / offsets alignments
def test_sparse(driver,ops):
 fresh();
 with open("/tmp/t/a","wb") as f:
  for off,data in ops: f.seek(off); f.write(data)
 run(["--driver",driver,"--reflink","never","--block-size","1KB","--no-progress","a","b"])
 if os.path.exists("/tmp/t/b"):
  a=pathlib.Path("/tmp/t/a").read_bytes();b=pathlib.Path("/tmp/t/b").read_bytes();print(" equal",a==b,"srcblk",os.stat("/tmp/t/a").st_blocks,"dstblk",os.stat("/tmp/t/b").st_blocks)
ops=[(0,b"x"*100),(5000,b"y"*100),(1023,b"z"),(1024*1024,b"END")]
for d in ["parfile","parblock"]: test_sparse(d,ops)
# cross fs parblock sparse repeat deterministic?
for i in range(3):
 fresh();
 with open("/tmp/t/a","wb") as f: f.write(b"start");f.seek(1024*1024);f.write(b"mid");f.seek(5*1024*1024);f.write(b"end")
 try:os.remove("/dev/shm/xcp_dest2")
 except:pass
 run(["--driver","parblock","--no-progress","a","/dev/shm/xcp_dest2"])
PY
python3 /tmp/p27.py 2>&1 | head -n 250
"}

