// ---------- logging ----------

struct Logger {
    level: LevelFilter,
    mutex: Mutex<()>,
}

fn hms_now() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as libc::time_t;
    let mut tm: libc::tm = unsafe { std::mem::zeroed() };
    unsafe { libc::localtime_r(&secs, &mut tm) };
    format!("{:02}:{:02}:{:02}", tm.tm_hour, tm.tm_min, tm.tm_sec)
}

fn thread_id_num() -> String {
    let dbg = format!("{:?}", thread::current().id());
    dbg.trim_start_matches("ThreadId(")
        .trim_end_matches(')')
        .to_string()
}

impl log::Log for Logger {
    fn enabled(&self, metadata: &log::Metadata<'_>) -> bool {
        metadata.level() <= self.level.to_level().unwrap_or(log::Level::Warn)
    }

    fn log(&self, record: &log::Record<'_>) {
        if !self.enabled(record.metadata()) {
            return;
        }
        let _guard = self.mutex.lock().unwrap_or_else(|e| e.into_inner());
        let level = record.level();
        let text = if level == log::Level::Debug || level == log::Level::Trace {
            format!(
                "{} [{}] ({}) {}: {}\n",
                hms_now(),
                level,
                thread_id_num(),
                record.target(),
                record.args()
            )
        } else {
            format!("{} [{}] {}\n", hms_now(), level, record.args())
        };
        if level == log::Level::Error {
            let mut err = io::stderr().lock();
            let _ = err.write_all(text.as_bytes());
            let _ = err.flush();
        } else {
            let mut out = io::stdout().lock();
            let _ = out.write_all(text.as_bytes());
            let _ = out.flush();
        }
    }

    fn flush(&self) {}
}

fn init_logger(verbose: u8) {
    let level = match verbose {
        0 => LevelFilter::Warn,
        1 => LevelFilter::Info,
        2 => LevelFilter::Debug,
        _ => LevelFilter::Trace,
    };
    let logger = Box::new(Logger {
        level,
        mutex: Mutex::new(()),
    });
    let _ = log::set_boxed_logger(logger);
    log::set_max_level(level);
}

// ---------- errors ----------

#[derive(Debug)]
enum XcpError {
    InvalidArguments(String),
    InvalidSource(String),
    InvalidDestination(String),
    DestinationExists(PathBuf),
    CopyError(String),
}

impl fmt::Display for XcpError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            XcpError::InvalidArguments(msg) => write!(f, "Invalid arguments: {}", msg),
            XcpError::InvalidSource(msg) => write!(f, "Invalid source: {}", msg),
            XcpError::InvalidDestination(msg) => {
                write!(f, "Invalid destination: {}", msg)
            }
            XcpError::DestinationExists(path) => write!(
                f,
                "Destination Exists: Destination file exists and --no-clobber is set., {}",
                path.display()
            ),
            XcpError::CopyError(msg) => write!(f, "Error during copy: {}", msg),
        }
    }
}

impl std::error::Error for XcpError {}

fn copy_io(e: io::Error) -> XcpError {
    XcpError::CopyError(e.to_string())
}

fn generic_join_error() -> AnyError {
    XcpError::CopyError("Error during copy operation".to_string()).into()
}

fn join_thread(handle: JoinHandle<AnyResult<()>>) -> AnyResult<()> {
    match handle.join() {
        Ok(result) => result,
        Err(_) => Err(generic_join_error()),
    }
}

// ---------- options / config ----------

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum DriverKind {
    ParFile,
    ParBlock,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ReflinkMode {
    Auto,
    Always,
    Never,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum BackupMode {
    None,
    Numbered,
    Auto,
}

#[derive(Debug)]
struct Config {
    recursive: bool,
    dereference: bool,
    workers: usize,
    block_size: u64,
    no_clobber: bool,
