}

fn parse_usize(s: &str) -> Result<usize, String> {
    s.parse::<usize>().map_err(|e| e.to_string())
}

fn parse_driver(s: &str) -> Result<DriverKind, String> {
    match s.to_lowercase().as_str() {
        "parfile" => Ok(DriverKind::ParFile),
        "parblock" => Ok(DriverKind::ParBlock),
        _ => Err(format!("Unknown driver: {}", s)),
    }
}

fn parse_reflink(s: &str) -> Result<ReflinkMode, String> {
    match s.to_lowercase().as_str() {
        "auto" => Ok(ReflinkMode::Auto),
        "always" => Ok(ReflinkMode::Always),
        "never" => Ok(ReflinkMode::Never),
        _ => Err(format!(
            "Invalid arguments: Unexpected value for 'reflink': {}",
            s
        )),
    }
}

fn parse_backup(s: &str) -> Result<BackupMode, String> {
    match s.to_lowercase().as_str() {
        "none" | "off" => Ok(BackupMode::None),
        "numbered" => Ok(BackupMode::Numbered),
        "auto" => Ok(BackupMode::Auto),
        _ => Err(format!(
            "Invalid arguments: Unexpected value for 'backup': {}",
            s
        )),
    }
}

fn parse_block_size(input: &str) -> Result<u64, String> {
    const ERR: &str = "could not interpret string as byte size";
    const TOO_LARGE: &str = "byte size too large";
    if input.is_empty() {
        // The reference's size parser panics on an empty input; a slice
        // access reproduces the same externally visible failure class.
        let _ = &input[..1];
    }
    let s = input.trim();
    if s.is_empty() {
        return Err(ERR.to_string());
    }
    // A repeated trailing B on a bare byte count (1BB, 1.5BBB) is accepted
    // by the reference parser, while 1KBB is not.
    let trailing_bs = s
        .chars()
        .rev()
        .take_while(|c| *c == 'b' || *c == 'B')
        .count();
    if trailing_bs >= 2 {
        let stem = &s[..s.len() - trailing_bs];
        if !stem.is_empty()
            && stem
                .chars()
                .last()
                .map(|c| c.is_ascii_digit() || c == '.')
                .unwrap_or(false)
        {
            if let Ok(v) = stem.parse::<f64>() {
                if !stem.starts_with('-') {
                    return Ok(v as u64);
                }
            }
        }
        return Err(ERR.to_string());
    }

    let lower = s.to_lowercase();
    let units: [(
        char,
        u64,
        u64,
    ); 6] = [
        ('k', 1_000, 1_024),
        ('m', 1_000_000, 1_048_576),
        ('g', 1_000_000_000, 1_073_741_824),
        ('t', 1_000_000_000_000, 1_099_511_627_776),
        ('p', 1_000_000_000_000_000, 1_125_899_906_842_624),
        ('e', 1_000_000_000_000_000_000, 1_152_921_504_606_846_976),
    ];
    let mut num_part: &str = s;
    let mut multiplier: u64 = 1;
    let mut has_suffix = false;

    for (unit, dec, bin) in units {
        let binary_suffix = format!("{}ib", unit);
        if lower.ends_with(&binary_suffix) {
            num_part = &s[..s.len() - 3];
            multiplier = bin;
            has_suffix = true;
            break;
        }
        let decimal_suffix = format!("{}b", unit);
        if lower.ends_with(&decimal_suffix) {
            num_part = &s[..s.len() - 2];
            multiplier = dec;
            has_suffix = true;
            break;
        }
    }
    if !has_suffix {
        if lower.ends_with('b') {
            num_part = &s[..s.len() - 1];
            multiplier = 1;
            has_suffix = true;
        } else if let Some(last) = lower.chars().last() {
            if let Some((_, dec, _)) = units.iter().find(|(u, _, _)| *u == last) {
                // Avoid treating the exponent marker of a plain float
                // such as "1e3" as a suffix: those end in a digit, so
                // this branch only fires for a bare trailing unit.
                num_part = &s[..s.len() - 1];
                multiplier = *dec;
                has_suffix = true;
            }
        }
    }

    let num_part = num_part.trim();
    if num_part.is_empty() || num_part.starts_with('-') {
        return Err(ERR.to_string());
    }
    let value: f64 = num_part.parse().map_err(|_| ERR.to_string())?;
    if !has_suffix && value.fract() > 0.0 {
        return Err(ERR.to_string());
    }
    let result = value * multiplier as f64;
    if has_suffix && result > u64::MAX as f64 {
        return Err(TOO_LARGE.to_string());
    }
    Ok(result as u64)
}

