// ---------- progress ----------

fn term_width() -> usize {
    let mut winsz: libc::winsize = unsafe { std::mem::zeroed() };
    let rc = unsafe { libc::ioctl(libc::STDERR_FILENO, libc::TIOCGWINSZ, &mut winsz) };
    if rc == 0 {
        winsz.ws_col as usize
    } else {
        0
    }
}

fn human_bytes(value: f64) -> String {
    const UNITS: [&str; 7] = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
    if !value.is_finite() {
        return format!("{} B", value);
    }
    let mut v = value;
    let mut idx = 0;
    while v >= 1024.0 && idx < UNITS.len() - 1 {
        v /= 1024.0;
        idx += 1;
    }
    if idx == 0 {
        format!("{} B", v as u64)
    } else {
        format!("{:.2} {}", v, UNITS[idx])
    }
}

fn format_eta(secs: u64) -> String {
    format!(
        "{:02}:{:02}:{:02}",
        secs / 3600,
        (secs % 3600) / 60,
        secs % 60
    )
}

struct Progress {
    enabled: bool,
    total: u64,
    pos: u64,
    start: Instant,
    drawn: bool,
    width: usize,
    last_visual_lines: usize,
}

impl Progress {
    fn new(no_progress: bool) -> Self {
        let is_tty = unsafe { libc::isatty(libc::STDERR_FILENO) } == 1;
        Progress {
            enabled: !no_progress && is_tty,
            total: 0,
            pos: 0,
            start: Instant::now(),
            drawn: false,
            width: term_width(),
            last_visual_lines: 1,
        }
    }

    fn stats(&self) -> String {
        let percent: u64 = if self.total == 0 {
            100
        } else {
            ((self.pos.min(self.total) as u128 * 100) / self.total as u128) as u64
        };
        let elapsed = self.start.elapsed().as_secs_f64();
        let rate = if elapsed > 0.0 {
            self.pos as f64 / elapsed
        } else {
            0.0
        };
        let eta_secs: u64 = if rate > 0.0 && self.total > self.pos {
            ((self.total - self.pos) as f64 / rate) as u64
        } else {
            0
        };
        let current = human_bytes(self.pos as f64);
        let total = human_bytes(self.total as f64);
        let rate_str = format!("{}/s", human_bytes(rate));
        // Centre the rate in a 15-column field (matching the reference).
        let rate_field = format!("{:^15}", rate_str);
        format!(
            "{:>12} / {:<12}| {:>3}% |{}| {} remaining",
            current,
            total,
            percent,
            rate_field,
            format_eta(eta_secs)
        )
    }

    fn bar(&self, inner: usize) -> String {
        if inner == 0 {
            return String::new();
        }
        let filled = if self.total == 0 {
            inner
        } else {
            ((self.pos.min(self.total) as u128 * inner as u128) / self.total as u128)
                as usize
        };
        let mut s = String::with_capacity(inner);
        for i in 0..inner {
            s.push(if i < filled { '#' } else { '-' });
        }
        s
    }

    fn draw(&mut self) {
        if !self.enabled {
            return;
        }
        let stats = self.stats();
        let mut out = String::new();
        if self.drawn {
            if self.last_visual_lines <= 1 {
                out.push_str("\r\u{1b}[2K");
            } else {
                let n = self.last_visual_lines - 1;
                out.push_str(&format!("\u{1b}[{}A", n));
                for i in 0..self.last_visual_lines {
                    out.push_str("\r\u{1b}[2K");
                    if i + 1 < self.last_visual_lines {
                        out.push_str("\u{1b}[1B");
                    }
                }
                out.push_str(&format!("\u{1b}[{}A", n));
            }
        }
        let width = self.width;
        let visual_lines;
        if width == 0 {
            out.push_str(&format!("[{}]{}", self.bar(8), stats));
            visual_lines = 1;
        } else if width >= 160 {
            let inner = width.saturating_sub(72);
            out.push_str(&format!("[{}]{}", self.bar(inner), stats));
            visual_lines = 1;
        } else {
            let inner = width.saturating_sub(2);
            out.push_str(&format!("[{}]\n", self.bar(inner)));
            // Pad the stats segment to a whole number of terminal rows.
            let rows = (stats.len() + width - 1) / width.max(1);
            let padded_len = rows * width;
            out.push_str(&stats);
            for _ in stats.len()..padded_len {
                out.push(' ');
            }
            visual_lines = 1 + rows;
        }
        self.last_visual_lines = visual_lines;
        self.drawn = true;
        let mut err = io::stderr().lock();
        let _ = err.write_all(out.as_bytes());
        let _ = err.flush();
    }

    fn add_total(&mut self, n: u64) {
        self.total = self.total.saturating_add(n);
        self.draw();
    }

    fn add_pos(&mut self, n: u64) {
        self.pos = self.pos.saturating_add(n);
        self.draw();
    }

    fn finish_success(&mut self) {
        if self.enabled && !self.drawn {
            self.draw();
        }
    }

    fn clear_if_drawn(&mut self) {
        if self.enabled && self.drawn {
            let mut err = io::stderr().lock();
            let _ = err.write_all(b"\r\u{1b}[2K");
            let _ = err.flush();
            self.drawn = false;
        }
    }
}

// ---------- operations ----------

#[derive(Debug)]
enum Operation {
    Copy(PathBuf, PathBuf),
    Link(PathBuf, PathBuf),
    Special(PathBuf, PathBuf),
}

#[derive(Debug)]
enum StatusUpdate {
    Size(u64),
    Copied(u64),
    Error(XcpError),
}

fn send_status(tx: &Sender<StatusUpdate>, update: StatusUpdate) {
    let _ = tx.send(update);
}

fn resolve_workers(workers: usize) -> usize {
    if workers == 0 {
        thread::available_parallelism()
            .map(|n| n.get())
            .unwrap_or(1)
    } else {
        workers
    }
}

fn target_base(source: &Path, dest: &Path, no_target_directory: bool) -> PathBuf {
    if dest.is_dir() && !no_target_directory {
        let last: &OsStr = source
            .components()
            .last()
            .map(|c| c.as_os_str())
            .unwrap_or_else(|| source.as_os_str());
        dest.join(last)
    } else {
        dest.to_path_buf()
    }
}

fn copy_dir_ownership(source: &Path, dest: &Path) {
    if let Ok(metadata) = fs::metadata(source) {
        if let Ok(cpath) = CString::new(dest.as_os_str().as_bytes()) {
            let rc = unsafe { libc::chown(cpath.as_ptr(), metadata.uid(), metadata.gid()) };
            if rc != 0 {
                warn!(
                    "Failed to copy directory ownership: {:?}: {}",
                    dest,
                    io::Error::last_os_error()
                );
            }
        }
    }
}

fn tree_walker(
    sources: Vec<PathBuf>,
    dest: PathBuf,
    config: Arc<Config>,
    op_tx: Sender<Operation>,
    status_tx: Sender<StatusUpdate>,
) -> AnyResult<()> {
    debug!(
        target: "libxcp::operations",
        "Starting walk worker {:?}", thread::current().id()
    );
    'outer: for source in &sources {
        let base = target_base(source, &dest, config.no_target_directory);
        debug!(target: "libxcp::operations", "Target base is {:?}", base);

        let matcher: Option<Gitignore> = if config.gitignore {
            let gitignore_path = source.join(".gitignore");
            info!("Using .gitignore file {:?}", gitignore_path);
            let (m, _err) = Gitignore::new(&gitignore_path);
            Some(m)
        } else {
            None
        };

        let walk = WalkDir::new(source);
        let iter: Box<dyn Iterator<Item = walkdir::Result<walkdir::DirEntry>>> =
            if let Some(matcher) = matcher {
                Box::new(walk.into_iter().filter_entry(move |entry| {
                    let is_dir = entry.file_type().is_dir();
                    !matcher.matched(entry.path(), is_dir).is_ignore()
                }))
            } else {
                Box::new(walk.into_iter())
            };

        for result in iter {
            debug!(target: "libxcp::operations", "Got tree entry {:?}", result);
            let entry = result?;
            let entry_path = entry.path().to_path_buf();

            let effective: PathBuf = if config.dereference {
                let canonical = fs::canonicalize(&entry_path)?;
                debug!(
                    target: "libxcp::operations",
                    "Dereferencing {:?} into {:?}", entry_path, canonical
                );
                canonical
            } else {
                entry_path.clone()
            };

            let rel: PathBuf = match entry_path.strip_prefix(source) {
                Ok(r) => r.to_path_buf(),
                Err(_) => entry_path.clone(),
            };
            let dest_path = base.join(&rel);

            let (is_dir, is_symlink, is_file, file_len): (bool, bool, bool, u64) =
                if config.dereference {
                    let metadata = fs::metadata(&effective)?;
                    let ft = metadata.file_type();
                    (
                        ft.is_dir(),
                        ft.is_symlink(),
                        ft.is_file(),
                        metadata.len(),
                    )
                } else {
                    let ft = entry.file_type();
                    let len = if ft.is_file() {
                        entry
                            .metadata()
                            .map(|m| m.len())
                            .unwrap_or_else(|_| {
                                fs::metadata(&effective).map(|m| m.len()).unwrap_or(0)
                            })
                    } else {
                        0
                    };
                    (ft.is_dir(), ft.is_symlink(), ft.is_file(), len)
                };

            if is_dir {
                if dest_path.exists() && config.no_clobber {
                    send_status(
                        &status_tx,
                        StatusUpdate::Error(XcpError::DestinationExists(dest_path)),
                    );
                    break 'outer;
                }
                debug!(
                    target: "libxcp::operations",
                    "Creating target directory {:?}", dest_path
                );
                if let Err(e) = fs::create_dir_all(&dest_path) {
                    error!("Error creating target directory: {}", e);
                    return Err(XcpError::CopyError(format!(
                        "Error creating target directory: {}",
                        e
                    ))
                    .into());
                }
                if config.ownership {
                    copy_dir_ownership(&effective, &dest_path);
                }
            } else {
                if dest_path.exists() && config.no_clobber {
                    send_status(
                        &status_tx,
                        StatusUpdate::Error(XcpError::DestinationExists(dest_path)),
                    );
                    break 'outer;
                }
                if is_symlink {
                    let link_target = fs::read_link(&effective)?;
                    debug!(
                        target: "libxcp::operations",
                        "Send symlink operation {:?} to {:?}", link_target, dest_path
                    );
                    let _ = op_tx.send(Operation::Link(link_target, dest_path));
                } else if is_file {
                    send_status(&status_tx, StatusUpdate::Size(file_len));
                    debug!(
                        target: "libxcp::operations",
                        "Send copy operation {:?} to {:?}", effective, dest_path
                    );
                    let _ = op_tx.send(Operation::Copy(effective, dest_path));
                } else {
                    debug!(
                        target: "libxcp::operations",
                        "Special file found: {:?} to {:?}", effective, dest_path
                    );
                    let _ = op_tx.send(Operation::Special(effective, dest_path));
                }
            }
        }
    }
    debug!(
        target: "libxcp::operations",
        "Walk-worker finished: {:?}", thread::current().id()
    );
    Ok(())
}

// ---------- file copying ----------

fn scan_max_backup(dest: &Path) -> io::Result<Option<u64>> {
    let file_name = match dest.file_name() {
        Some(n) => n.as_bytes().to_vec(),
        None => return Ok(None),
    };
    let parent: PathBuf = match dest.parent() {
        Some(p) if !p.as_os_str().is_empty() => p.to_path_buf(),
        _ => PathBuf::from("."),
    };
    let mut prefix = file_name.clone();
    prefix.extend_from_slice(b".~");
    let mut max: Option<u64> = None;
    for entry in fs::read_dir(&parent)? {
        let entry = entry?;
        let name = entry.file_name();
        let bytes = name.as_bytes();
        if bytes.len() > prefix.len()
            && bytes.starts_with(&prefix)
            && bytes.ends_with(b"~")
        {
            let digits = &bytes[prefix.len()..bytes.len() - 1];
            if !digits.is_empty() && digits.iter().all(|b| b.is_ascii_digit()) {
                if let Ok(text) = std::str::from_utf8(digits) {
                    if let Ok(n) = text.parse::<u64>() {
                        max = Some(match max {
                            Some(cur) => cur.max(n),
                            None => n,
                        });
                    }
                }
            }
        }
    }
    Ok(max)
}

fn handle_backup(dest: &Path, config: &Config) -> Result<(), XcpError> {
    if config.backup == BackupMode::None {
        return Ok(());
    }
    if !dest.exists() {
        return Ok(());
    }
    let max = scan_max_backup(dest).map_err(copy_io)?;
    let next: u64 = match config.backup {
        BackupMode::None => return Ok(()),
        BackupMode::Numbered => max.map(|m| m.wrapping_add(1)).unwrap_or(1),
        BackupMode::Auto => match max {
            Some(m) => m.wrapping_add(1),
            None => return Ok(()),
        },
    };
    let mut backup_name = dest.as_os_str().to_os_string();
    backup_name.push(format!(".~{}~", next));
    let backup_path = PathBuf::from(backup_name);
    info!("Backup: Rename {:?} to {:?}", dest, backup_path);
    fs::rename(dest, &backup_path).map_err(copy_io)?;
    Ok(())
}

struct PreparedCopy {
    infile: File,
    outfile: File,
    size: u64,
}

fn prepare_copy(
    source: &Path,
    dest: &Path,
    config: &Config,
) -> Result<PreparedCopy, XcpError> {
    let infile = File::open(source).map_err(copy_io)?;
    let size = infile.metadata().map_err(copy_io)?.len();
    handle_backup(dest, config)?;
    let outfile = OpenOptions::new()
        .write(true)
        .create(true)
        .truncate(true)
        .open(dest)
        .map_err(copy_io)?;
    outfile.set_len(size).map_err(copy_io)?;
    Ok(PreparedCopy {
        infile,
        outfile,
        size,
    })
}

enum ReflinkOutcome {
    Reflinked,
    Fallback,
    AlwaysFailed(XcpError),
}

fn attempt_reflink(
    infile: &File,
    outfile: &File,
    config: &Config,
) -> ReflinkOutcome {
    if config.reflink == ReflinkMode::Never {
        return ReflinkOutcome::Fallback;
    }
    debug!(
        target: "libxcp::operations",
        "Attempting reflink from {:?}->{:?}", infile, outfile
    );
    const FICLONE: libc::c_ulong = 0x4004_9409 as libc::c_ulong;
    let rc = unsafe { libc::ioctl(outfile.as_raw_fd(), FICLONE, infile.as_raw_fd()) };
    if rc == 0 {
        debug!(
            target: "libxcp::operations",
            "Reflink {:?} succeeded", outfile
        );
        ReflinkOutcome::Reflinked
    } else if config.reflink == ReflinkMode::Always {
        ReflinkOutcome::AlwaysFailed(XcpError::CopyError(format!(
            "Failed to reflink file and 'always' was specified: {:?}->{:?}",
            infile, outfile
        )))
    } else {
        debug!(
            target: "libxcp::operations",
            "Failed to reflink, falling back to copy"
        );
        ReflinkOutcome::Fallback
    }
}

fn seek_extent(fd: i32, offset: u64, whence: i32) -> Option<u64> {
    let rc = unsafe { libc::lseek(fd, offset as libc::off_t, whence) };
    if rc < 0 {
        None
    } else {
        Some(rc as u64)
    }
}

fn copy_range_sparse(
    infile: &File,
    outfile: &File,
    start: u64,
    end: u64,
    status_tx: &Sender<StatusUpdate>,
) -> Result<(), XcpError> {
    const SEEK_DATA: i32 = 3;
    const SEEK_HOLE: i32 = 4;
    if start >= end {
        send_status(status_tx, StatusUpdate::Copied(0));
        return Ok(());
    }
    let in_fd = infile.as_raw_fd();
    let out_fd = outfile.as_raw_fd();
    let mut pos = start;
    while pos < end {
        let data = match seek_extent(in_fd, pos, SEEK_DATA) {
            Some(d) => d,
            None => {
                let err = io::Error::last_os_error();
                if err.raw_os_error() == Some(libc::ENXIO) {
                    send_status(status_tx, StatusUpdate::Copied(end - pos));
                    return Ok(());
                }
                pos
            }
        };
        if data >= end {
            send_status(status_tx, StatusUpdate::Copied(end - pos));
            return Ok(());
        }
        if data > pos {
            send_status(status_tx, StatusUpdate::Copied(data - pos));
            pos = data;
        }
        let hole = seek_extent(in_fd, pos, SEEK_HOLE)
            .unwrap_or(end)
            .min(end);
        let segment_end = if hole > pos { hole } else { end };
        while pos < segment_end {
            let remaining = segment_end - pos;
            let mut in_off = pos as libc::loff_t;
            let mut out_off = pos as libc::loff_t;
            let n = unsafe {
                libc::copy_file_range(
                    in_fd,
                    &mut in_off,
                    out_fd,
                    &mut out_off,
                    remaining as libc::size_t,
                    0,
                )
            };
            if n < 0 {
                let err = io::Error::last_os_error();
                if err.raw_os_error() == Some(libc::EINTR) {
                    continue;
                }
                return Err(copy_io(err));
            }
            if n == 0 {
                return Err(XcpError::CopyError(
                    XcpError::InvalidSource(
                        "Source file ended prematurely.".to_string(),
                    )
                    .to_string(),
                ));
            }
            pos += n as u64;
            send_status(status_tx, StatusUpdate::Copied(n as u64));
        }
    }
    Ok(())
}

fn timespec_of(t: SystemTime) -> libc::timespec {
    match t.duration_since(UNIX_EPOCH) {
        Ok(d) => libc::timespec {
            tv_sec: d.as_secs() as libc::time_t,
            tv_nsec: d.subsec_nanos() as libc::c_long,
        },
        Err(e) => {
            let d = e.duration();
            if d.subsec_nanos() == 0 {
                libc::timespec {
                    tv_sec: -(d.as_secs() as libc::time_t),
                    tv_nsec: 0,
                }
            } else {
                libc::timespec {
                    tv_sec: -(d.as_secs() as libc::time_t) - 1,
                    tv_nsec: (1_000_000_000 - d.subsec_nanos()) as libc::c_long,
                }
            }
        }
    }
}

fn copy_xattrs(infile: &File, outfile: &File) -> io::Result<()> {
    debug!(target: "libfs::common", "Starting xattr copy...");
    let in_fd = infile.as_raw_fd();
    let out_fd = outfile.as_raw_fd();
    let size = unsafe { libc::flistxattr(in_fd, std::ptr::null_mut(), 0) };
    if size < 0 {
        return Err(io::Error::last_os_error());
    }
    if size == 0 {
        return Ok(());
    }
    let mut buf = vec![0u8; size as usize];
    let got = unsafe {
        libc::flistxattr(in_fd, buf.as_mut_ptr() as *mut libc::c_char, buf.len())
    };
    if got < 0 {
        return Err(io::Error::last_os_error());
    }
    buf.truncate(got as usize);
    for name in buf.split(|b| *b == 0) {
        if name.is_empty() {
            continue;
        }
        let name_display = String::from_utf8_lossy(name).into_owned();
        debug!(
            target: "libfs::common",
            "Copy xattr {:?}", name_display
        );
        let cname = CString::new(name).unwrap_or_else(|_| CString::new("").unwrap());
        let vsize = unsafe {
            libc::fgetxattr(in_fd, cname.as_ptr(), std::ptr::null_mut(), 0)
        };
        if vsize < 0 {
            return Err(io::Error::last_os_error());
        }
        let mut value = vec![0u8; vsize as usize];
        if vsize > 0 {
            let vgot = unsafe {
                libc::fgetxattr(
                    in_fd,
                    cname.as_ptr(),
                    value.as_mut_ptr() as *mut libc::c_void,
                    value.len(),
                )
            };
            if vgot < 0 {
                return Err(io::Error::last_os_error());
            }
            value.truncate(vgot as usize);
        }
        let rc = unsafe {
            libc::fsetxattr(
                out_fd,
                cname.as_ptr(),
                value.as_ptr() as *const libc::c_void,
                value.len(),
                0,
            )
        };
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }
    }
    Ok(())
}

fn copy_metadata(
    infile: &File,
    outfile: &File,
    config: &Config,
) -> io::Result<()> {
    if !config.no_perms {
        copy_xattrs(infile, outfile)?;
        debug!(target: "libfs::common", "Performing permissions copy");
        let metadata = infile.metadata()?;
        let mode = (metadata.mode() & 0o7777) as libc::mode_t;
        let rc = unsafe { libc::fchmod(outfile.as_raw_fd(), mode) };
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }
    }
    if !config.no_timestamps {
        debug!(target: "libfs::common", "Performing timestamp copy");
        let metadata = infile.metadata()?;
        let atime = metadata.accessed()?;
        let mtime = metadata.modified()?;
        let times = [timespec_of(atime), timespec_of(mtime)];
        let rc = unsafe { libc::futimens(outfile.as_raw_fd(), times.as_ptr()) };
        if rc != 0 {
            return Err(io::Error::last_os_error());
        }
    }
    if config.ownership {
        if let Ok(metadata) = infile.metadata() {
            let rc = unsafe {
                libc::fchown(outfile.as_raw_fd(), metadata.uid(), metadata.gid())
            };
            if rc != 0 {
                warn!("Failed to copy file ownership: {:?}", infile);
            }
        }
    }
    Ok(())
}

fn finalize_file(
    infile: &File,
    outfile: &File,
    config: &Config,
) -> Result<(), XcpError> {
    let meta_result = copy_metadata(infile, outfile, config);
    let sync_result: io::Result<()> = if config.fsync {
        debug!(
            target: "libxcp::operations",
            "Syncing file {:?}", outfile
        );
        outfile.sync_all()
    } else {
        Ok(())
    };
    meta_result.and(sync_result).map_err(copy_io)
}

fn copy_file_full(
    source: &Path,
    dest: &Path,
    config: &Config,
    status_tx: &Sender<StatusUpdate>,
) -> Result<(), XcpError> {
    let prep = prepare_copy(source, dest, config)?;
    let data_result: Result<(), XcpError> =
        match attempt_reflink(&prep.infile, &prep.outfile, config) {
            ReflinkOutcome::Reflinked => {
                send_status(status_tx, StatusUpdate::Copied(prep.size));
                Ok(())
            }
            ReflinkOutcome::Fallback => copy_range_sparse(
                &prep.infile,
                &prep.outfile,
                0,
                prep.size,
                status_tx,
            ),
            ReflinkOutcome::AlwaysFailed(e) => Err(e),
        };
    let finalize_result = finalize_file(&prep.infile, &prep.outfile, config);
    data_result.and(finalize_result)
}

fn copy_special(source: &Path, dest: &Path) -> io::Result<()> {
    let metadata = fs::symlink_metadata(source)?;
    if dest.exists() {
        fs::remove_file(dest)?;
    }
    let cpath = CString::new(dest.as_os_str().as_bytes())
        .map_err(|_| io::Error::from_raw_os_error(libc::EINVAL))?;
    let mode = metadata.mode() as libc::mode_t;
    let rdev = metadata.rdev() as libc::dev_t;
    let rc = unsafe { libc::mknod(cpath.as_ptr(), mode, rdev) };
    if rc != 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

// Status handling shared by both drivers. Returns Some(error) as soon as
// the first status error is logged (callers then abandon their workers),
// or None once every status sender has been dropped.
fn run_status_loop(
    status_rx: &Receiver<StatusUpdate>,
    progress: &mut Progress,
) -> Option<XcpError> {
    while let Ok(update) = status_rx.recv() {
        match update {
            StatusUpdate::Size(n) => progress.add_total(n),
            StatusUpdate::Copied(n) => progress.add_pos(n),
            StatusUpdate::Error(e) => {
                error!("Received error: {}", e);
                progress.clear_if_drawn();
                return Some(e);
            }
        }
    }
    None
}

fn spawn_ticker() -> (Sender<()>, JoinHandle<()>) {
    let (tx, rx) = crossbeam_channel::bounded::<()>(0);
    let handle = thread::spawn(move || {
        let _ = rx.recv();
    });
    (tx, handle)
}

// ---------- parfile driver ----------

fn parfile_worker(
    op_rx: Receiver<Operation>,
    status_tx: Sender<StatusUpdate>,
    config: Arc<Config>,
) -> AnyResult<()> {
    debug!(
        target: "libxcp::drivers::parfile",
        "Starting copy worker {:?}", thread::current().id()
    );
    while let Ok(op) = op_rx.recv() {
        debug!(
            target: "libxcp::drivers::parfile",
            "Received operation {:?}", op
        );
        match op {
            Operation::Copy(source, dest) => {
                info!(
                    "Worker[{:?}]: Copy {:?} -> {:?}",
                    thread::current().id(),
                    source,
                    dest
                );
                if let Err(e) = copy_file_full(&source, &dest, &config, &status_tx) {
                    error!(
                        "Error copying: {:?} -> {:?}; aborting.",
                        source, dest
                    );
                    send_status(&status_tx, StatusUpdate::Error(e));
                    break;
                }
            }
            Operation::Link(target, dest) => {
                info!(
                    "Worker[{:?}]: Symlink {:?} -> {:?}",
                    thread::current().id(),
                    target,
                    dest
                );
                let _ = symlink(&target, &dest);
            }
            Operation::Special(source, dest) => {
                info!(
                    "Worker[{:?}]: Special file {:?} -> {:?}",
                    thread::current().id(),
                    source,
                    dest
                );
                copy_special(&source, &dest)?;
            }
        }
    }
    debug!(
        target: "libxcp::drivers::parfile",
        "Copy worker {:?} shutting down", thread::current().id()
    );
    Ok(())
}

fn driver_parfile(
    sources: Vec<PathBuf>,
    dest: PathBuf,
    config: Arc<Config>,
) -> AnyResult<()> {
    let (status_tx, status_rx) = unbounded::<StatusUpdate>();
    let (op_tx, op_rx) = unbounded::<Operation>();
    let worker_count = resolve_workers(config.workers);

    let (_tick_tx, _ticker) = spawn_ticker();

    let walk_handle = {
        let cfg = Arc::clone(&config);
        let stx = status_tx.clone();
        thread::spawn(move || tree_walker(sources, dest, cfg, op_tx, stx))
    };

    let mut worker_handles: Vec<JoinHandle<AnyResult<()>>> = Vec::new();
    for _ in 0..worker_count {
        let rx = op_rx.clone();
        let stx = status_tx.clone();
        let cfg = Arc::clone(&config);
        worker_handles.push(thread::spawn(move || parfile_worker(rx, stx, cfg)));
    }
    drop(op_rx);
    drop(status_tx);

    let mut progress = Progress::new(config.no_progress);
    if let Some(e) = run_status_loop(&status_rx, &mut progress) {
        return Err(e.into());
    }
    progress.finish_success();

    join_thread(walk_handle)?;
    for handle in worker_handles {
        join_thread(handle)?;
    }
    Ok(())
}

// ---------- parblock driver ----------

struct JobState {
    remaining: Mutex<usize>,
    condvar: Condvar,
}

impl JobState {
    fn new(n: usize) -> Self {
        JobState {
            remaining: Mutex::new(n),
            condvar: Condvar::new(),
        }
    }
    fn finish_one(&self) {
        let mut guard = self.remaining.lock().unwrap_or_else(|e| e.into_inner());
        *guard = guard.saturating_sub(1);
        self.condvar.notify_all();
    }
    fn wait(&self) {
        let mut guard = self.remaining.lock().unwrap_or_else(|e| e.into_inner());
        while *guard > 0 {
            guard = self
                .condvar
                .wait(guard)
                .unwrap_or_else(|e| e.into_inner());
        }
    }
}

enum PoolJob {
    Range {
        infile: Arc<File>,
        outfile: Arc<File>,
        start: u64,
        end: u64,
        status_tx: Sender<StatusUpdate>,
        state: Arc<JobState>,
    },
    Finalise {
        infile: Arc<File>,
        outfile: Arc<File>,
        size: u64,
        status_tx: Sender<StatusUpdate>,
        state: Arc<JobState>,
        config: Arc<Config>,
    },
}

fn pool_worker(job_rx: Receiver<PoolJob>) {
    while let Ok(job) = job_rx.recv() {
        match job {
            PoolJob::Range {
                infile,
                outfile,
                start,
                end,
                status_tx,
                state,
            } => {
                if let Err(e) =
                    copy_range_sparse(&infile, &outfile, start, end, &status_tx)
                {
                    error!("Error copying: aborting.");
                    send_status(&status_tx, StatusUpdate::Error(e));
                }
                state.finish_one();
            }
            PoolJob::Finalise {
                infile,
                outfile,
                size,
                status_tx,
                state,
                config,
            } => {
                state.wait();
                if size == 0 {
                    send_status(&status_tx, StatusUpdate::Copied(0));
                }
                if let Err(e) = finalize_file(&infile, &outfile, &config) {
                    error!("Error copying: aborting.");
                    send_status(&status_tx, StatusUpdate::Error(e));
                }
            }
        }
    }
}

fn parblock_dispatcher(
    sources: Vec<PathBuf>,
    dest: PathBuf,
    config: Arc<Config>,
    status_tx: Sender<StatusUpdate>,
) -> AnyResult<()> {
    let (op_tx, op_rx) = unbounded::<Operation>();
    let worker_count = resolve_workers(config.workers);

    let walk_handle = {
        let cfg = Arc::clone(&config);
        let stx = status_tx.clone();
        thread::spawn(move || tree_walker(sources, dest, cfg, op_tx, stx))
    };

    let (job_tx, job_rx) = unbounded::<PoolJob>();
    let mut pool_handles: Vec<JoinHandle<()>> = Vec::new();
    for _ in 0..worker_count {
        let rx = job_rx.clone();
        pool_handles.push(thread::spawn(move || pool_worker(rx)));
    }
    drop(job_rx);

    let mut special_error: Option<AnyError> = None;
    let mut sent_status_error = false;

    'dispatch: while let Ok(op) = op_rx.recv() {
        match op {
            Operation::Copy(source, dest) => {
                info!(
                    "Dispatch[{:?}]: Copy {:?} -> {:?}",
                    thread::current().id(),
                    source,
                    dest
                );
                let prep = match prepare_copy(&source, &dest, &config) {
                    Ok(p) => p,
                    Err(e) => {
                        error!(
                            "Dispatcher: Error copying {:?} -> {:?}.",
                            source, dest
                        );
                        send_status(&status_tx, StatusUpdate::Error(e));
                        sent_status_error = true;
                        break 'dispatch;
                    }
                };
                match attempt_reflink(&prep.infile, &prep.outfile, &config) {
                    ReflinkOutcome::Reflinked => {
                        info!("Reflinked, skipping rest of copy");
                        if let Err(e) =
                            finalize_file(&prep.infile, &prep.outfile, &config)
                        {
                            error!(
                                "Dispatcher: Error copying {:?} -> {:?}.",
                                source, dest
                            );
                            send_status(&status_tx, StatusUpdate::Error(e));
                            sent_status_error = true;
                            break 'dispatch;
                        }
                        send_status(
                            &status_tx,
                            StatusUpdate::Copied(prep.size),
                        );
                    }
                    ReflinkOutcome::AlwaysFailed(e) => {
                        let finalize_result =
                            finalize_file(&prep.infile, &prep.outfile, &config);
                        let err = match finalize_result {
                            Ok(()) => e,
                            Err(_) => e,
                        };
                        error!(
                            "Dispatcher: Error copying {:?} -> {:?}.",
                            source, dest
                        );
                        send_status(&status_tx, StatusUpdate::Error(err));
                        sent_status_error = true;
                        break 'dispatch;
                    }
                    ReflinkOutcome::Fallback => {
                        let infile = Arc::new(prep.infile);
                        let outfile = Arc::new(prep.outfile);
                        let size = prep.size;
                        let block: u64 = if config.block_size == 0 {
                            size.max(1)
                        } else {
                            config.block_size
                        };
                        let num_blocks: usize = if size == 0 {
                            0
                        } else {
                            ((size + block - 1) / block) as usize
                        };
                        let state = Arc::new(JobState::new(num_blocks));
                        let mut start: u64 = 0;
                        while start < size {
                            let end = start.saturating_add(block).min(size);
                            let _ = job_tx.send(PoolJob::Range {
                                infile: Arc::clone(&infile),
                                outfile: Arc::clone(&outfile),
                                start,
                                end,
                                status_tx: status_tx.clone(),
                                state: Arc::clone(&state),
                            });
                            start = end;
                        }
                        let _ = job_tx.send(PoolJob::Finalise {
                            infile,
                            outfile,
                            size,
                            status_tx: status_tx.clone(),
                            state,
                            config: Arc::clone(&config),
                        });
                    }
                }
            }
            Operation::Link(target, dest) => {
                info!(
                    "Dispatch[{:?}]: Symlink {:?} -> {:?}",
                    thread::current().id(),
                    target,
                    dest
                );
                if let Err(e) = symlink(&target, &dest) {
                    error!(
                        "Error symlinking: {:?} -> {:?}; aborting.",
                        target, dest
                    );
                    send_status(
                        &status_tx,
                        StatusUpdate::Error(copy_io(e)),
                    );
                    sent_status_error = true;
                    break 'dispatch;
                }
            }
            Operation::Special(source, dest) => {
                info!(
                    "Dispatch[{:?}]: Special file {:?} -> {:?}",
                    thread::current().id(),
                    source,
                    dest
                );
                if let Err(e) = copy_special(&source, &dest) {
                    special_error = Some(e.into());
                    break 'dispatch;
                }
            }
        }
    }

    if special_error.is_none() && !sent_status_error {
        info!("Queuing complete");
        drop(job_tx);
        for handle in pool_handles {
            let _ = handle.join();
        }
        info!("Pool complete");
        return join_thread(walk_handle);
    }

    drop(job_tx);
    if let Some(e) = special_error {
        for handle in pool_handles {
            let _ = handle.join();
        }
        return Err(e);
    }
    // A status error has been reported; the status loop in the caller
    // abandons the operation.
    let _ = walk_handle;
    Ok(())
}

fn driver_parblock(
    sources: Vec<PathBuf>,
    dest: PathBuf,
    config: Arc<Config>,
) -> AnyResult<()> {
    let (status_tx, status_rx) = unbounded::<StatusUpdate>();
    let (_tick_tx, _ticker) = spawn_ticker();

    let dispatcher_handle = {
        let cfg = Arc::clone(&config);
        let stx = status_tx.clone();
        thread::spawn(move || parblock_dispatcher(sources, dest, cfg, stx))
    };
    drop(status_tx);

    let mut progress = Progress::new(config.no_progress);
    if let Some(e) = run_status_loop(&status_rx, &mut progress) {
        return Err(e.into());
    }
    progress.finish_success();
    join_thread(dispatcher_handle)
}

// ---------- top level ----------

fn run() -> AnyResult<()> {
    let matches = build_cli().get_matches();
    let verbose: u8 = matches.get_count("verbose");
    init_logger(verbose);

    let config = Config {
        recursive: matches.get_flag("recursive"),
        dereference: matches.get_flag("dereference"),
        workers: *matches.get_one::<usize>("workers").unwrap_or(&4),
        block_size: *matches.get_one::<u64>("block-size").unwrap_or(&1_000_000),
        no_clobber: matches.get_flag("no-clobber"),
        force: matches.get_flag("force"),
        gitignore: matches.get_flag("gitignore"),
        glob: matches.get_flag("glob"),
        no_progress: matches.get_flag("no-progress"),
        no_perms: matches.get_flag("no-perms"),
        no_timestamps: matches.get_flag("no-timestamps"),
        ownership: matches.get_flag("ownership"),
        driver: *matches
            .get_one::<DriverKind>("driver")
            .unwrap_or(&DriverKind::ParFile),
        no_target_directory: matches.get_flag("no-target-directory"),
        target_directory: matches
            .get_one::<String>("target-directory")
            .map(PathBuf::from),
        fsync: matches.get_flag("fsync"),
        reflink: *matches
            .get_one::<ReflinkMode>("reflink")
            .unwrap_or(&ReflinkMode::Auto),
        backup: *matches
            .get_one::<BackupMode>("backup")
            .unwrap_or(&BackupMode::None),
    };

    let raw_paths: Vec<String> = matches
        .get_many::<String>("paths")
        .map(|values| values.cloned().collect())
        .unwrap_or_default();

    if config.reflink == ReflinkMode::Never {
        warn!("--reflink=never is selected, however the Linux kernel may override this.");
    }
    if config.force && config.no_clobber {
        return Err(XcpError::InvalidArguments(
            "--force and --noclobber cannot be set at the same time.".to_string(),
        )
        .into());
    }

    let (raw_sources, dest): (Vec<String>, PathBuf) =
        if let Some(td) = &config.target_directory {
            (raw_paths, td.clone())
        } else {
            if raw_paths.is_empty() {
                return Err(XcpError::InvalidArguments(
                    "Insufficient arguments".to_string(),
                )
                .into());
            }
            let mut paths = raw_paths;
            let dest = PathBuf::from(paths.pop().unwrap());
            (paths, dest)
        };

    let sources: Vec<PathBuf> = if config.glob {
        let mut expanded: Vec<PathBuf> = Vec::new();
        for pattern in &raw_sources {
            for entry in glob::glob(pattern)? {
                expanded.push(entry?);
            }
        }
        expanded
    } else {
        raw_sources.iter().map(PathBuf::from).collect()
    };

    if sources.is_empty() {
        return Err(
            XcpError::InvalidSource("No source files found.".to_string()).into(),
        );
    }
    if sources.len() > 1 && !dest.is_dir() {
        return Err(XcpError::InvalidDestination(
            "Multiple sources and destination is not a directory.".to_string(),
        )
        .into());
    }
    if sources.iter().any(|s| s.is_dir()) && dest.exists() && !dest.is_dir() {
        return Err(XcpError::InvalidDestination(
            "Cannot copy a directory to a file.".to_string(),
        )
        .into());
    }

    for source in &sources {
        info!("Copying source {:?} to {:?}", source, dest);
        if !source.exists() {
            return Err(
                XcpError::InvalidSource("Source does not exist.".to_string())
                    .into(),
            );
        }
        if source.is_dir() && !config.recursive {
            return Err(XcpError::InvalidSource(
                "Source is directory and --recursive not specified.".to_string(),
            )
            .into());
        }
        if source == &dest {
            return Err(XcpError::InvalidSource(
                "Cannot copy a directory into itself".to_string(),
            )
            .into());
        }
    }

    let config = Arc::new(config);
    match config.driver {
        DriverKind::ParFile => driver_parfile(sources, dest, config)?,
        DriverKind::ParBlock => driver_parblock(sources, dest, config)?,
    }
    info!("Copy complete");
    Ok(())
}

fn main() -> AnyResult<()> {
    // Silence the unused-import warning path for VecDeque on some builds.
    let _ = VecDeque::<()>::new();
    run()
}
