        if r.random()<.3:
            os.makedirs(root+'/dest/src/dir0',exist_ok=True)
    if r.random()<.3:
        pathlib.Path(root+'/dest/stale').write_text('stale')
    # .gitignore
    pathlib.Path(root+'/src/.gitignore').write_text(r.choice(['*.bin\n','f1*\n','dir0/\n','*.bin\n!f2.bin\n','']))

