{"command":"python3 - <<'PY'
import subprocess,os,pathlib,collections
os.makedirs('/tmp/t',exist_ok=True);pathlib.Path('/tmp/t/a').write_text('x')
counts=collections.Counter()
for i in range(200):
 p=subprocess.run(['/workspace/executable','--no-progress','a','x/y/b'],cwd='/tmp/t',capture_output=True,text=True)
 lines=p.stderr.splitlines()
 # classify first word patterns ignoring time
 kinds=[]
 for l in lines:
  if 'Error copying:' in l:kinds.append('C')
  elif 'Received error:' in l:kinds.append('R')
  elif l.startswith('Error:'):kinds.append('F')
 counts[''.join(kinds)]+=1
print(counts)
# parblock symlink error ordering
counts=collections.Counter()
for i in range(200):
 pathlib.Path('/tmp/t/real').write_text('x')
 try:os.symlink('real','/tmp/t/link')
 except:pass
 pathlib.Path('/tmp/t/b').write_text('old')
 p=subprocess.run(['/workspace/executable','--driver','parblock','--no-progress','link','b'],cwd='/tmp/t',capture_output=True,text=True)
 kinds=[]
 for l in p.stderr.splitlines():
  if 'Error symlinking:' in l:kinds.append('S')
  elif 'Received error:' in l:kinds.append('R')
  elif l.startswith('Error:'):kinds.append('F')
 counts[''.join(kinds)]+=1
print('symlink',counts)
PY
